    const uint64_t region_start64 = static_cast<uint64_t>(region_start);
    const uint64_t region_size64 = static_cast<uint64_t>(region_size);

    // Widened, non-wrapping end addresses.
    const uint64_t end = base64 + length64;
    const uint64_t region_end = region_start64 + region_size64;

    // BUG: the lower-bound containment check (base64 >= region_start64) has
    // been dropped, so any transfer whose end address happens to fall
    // within the region is accepted even if it starts before region_start,
    // violating full-containment semantics (partial-containment bypass).
    if (end <= region_end) {
        return 1;
    }

    return 0;
}

