    // BUG: uses strict '>' instead of '>=' for the start comparison, so a
    // transfer that starts exactly at region_start (a valid, fully
    // contained case per FR1) is incorrectly rejected.
    if (base64 > region_start64 && end <= region_end) {
        return 1;
    }

    return 0;
